/* eslint-disable @typescript-eslint/no-explicit-any */
"use client";
import Link from "next/link";
import React, { FC, useState, useEffect } from "react";
import NavItems from "../utills/NavItems";
import { ThemeSwitcher } from "../utills/ThemeSwitcher";
import { MdOutlineMenu, MdPerson, MdClose } from "react-icons/md";
import { HiOutlineShoppingCart } from "react-icons/hi";
import CustomModel from "../utills/CustomModel";
import Login from "./auth/Login";
import SignUp from "./auth/SignUp";
import Verification from "./auth/Verification";
import { useSelector } from "react-redux";
import Image from "next/image";
import avatar from "../../public/avatar.jpg";
import { useSession } from "next-auth/react";
import {
  useLogoutQuery,
  useSocialAuthMutation,
} from "@/redux/features/auth/authApi";
import { toast } from "react-hot-toast";

type Props = {
  open: boolean;
  setOpen: (open: boolean) => void;
  activeItem: number;
  route: string;
  setRoute: (route: string) => void;
};

const Header: FC<Props> = ({ activeItem, setOpen, open, route, setRoute }) => {
  const [scrolled, setScrolled] = useState(false);
  const [openSideBar, setOpenSideBar] = useState(false);

  const { user: dataUser } = useSelector((state: any) => state.auth);
  const { data: session } = useSession();
  const [socialAuth, { isSuccess }] = useSocialAuthMutation();
  const [logout, setLogout] = useState(false);
  useLogoutQuery(undefined, { skip: !logout });

  // Parse user safely
  const user = dataUser ? JSON.parse(dataUser) : null;

  // Social auth effect
  useEffect(() => {
    if (!user && session) {
      socialAuth({
        name: session.user?.name,
        email: session.user?.email,
        avatar: session.user?.image,
      });
    }
    if (session === null) {
      if (isSuccess) toast.success("Login successful");
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setLogout(true);
    }
  }, [user, session, isSuccess]);

  // Scroll effect
  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 80);
    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  // Close sidebar on overlay click
  const handleOverlayClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if ((e.target as HTMLElement).id === "overlay") setOpenSideBar(false);
  };

  return (
    <div className="w-full relative">
      {/* ── Navbar ── */}
      <header
        className={`fixed top-0 left-0 w-full h-[70px] z-50 transition-all duration-300
          bg-white dark:bg-gray-900
          border-b border-gray-200 dark:border-gray-800
          ${scrolled ? "shadow-sm" : ""}
        `}
      >
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-full flex items-center justify-between">
          {/* Logo */}
          <Link href="/" className="flex items-center gap-2">
            <div className="w-9 h-9 bg-gradient-to-br from-blue-600 to-purple-600 rounded-lg flex items-center justify-center">
              <span className="text-white font-bold text-lg">E</span>
            </div>
            <span className="text-xl font-bold bg-gradient-to-r from-blue-600 to-purple-600 bg-clip-text text-transparent">
              ELearning
            </span>
          </Link>

          {/* Desktop nav */}
          <nav className="hidden lg:flex items-center gap-8">
            <NavItems activeItem={activeItem} isMobile={false} />
          </nav>

          {/* Right actions */}
          <div className="flex items-center gap-2">
            {/* Cart */}
            <button className="relative p-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors">
              <HiOutlineShoppingCart className="w-5 h-5 text-gray-600 dark:text-gray-300" />
              <span className="absolute top-0.5 right-0.5 w-4 h-4 bg-red-500 text-white text-[10px] rounded-full flex items-center justify-center font-semibold">
                0
              </span>
            </button>

            {/* Theme */}
            <ThemeSwitcher />

            {/* Avatar or Sign In */}
            {user ? (
              <Link href="/profile">
                <Image
                  src={user?.avatar?.url || avatar}
                  alt="avatar"
                  width={36}
                  height={36}
                  className="rounded-full object-cover transition-all"
                  style={{
                    outline:
                      activeItem === 5
                        ? "2px solid #ffc102"
                        : "2px solid transparent",
                    outlineOffset: "2px",
                  }}
                />
              </Link>
            ) : (
              <button
                onClick={() => setOpen(true)}
                className="hidden lg:flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-blue-600 to-purple-600 text-white text-sm font-medium rounded-full hover:opacity-90 transition-opacity"
              >
                <MdPerson size={18} />
                Sign In
              </button>
            )}

            {/* Mobile menu */}
            <button
              onClick={() => setOpenSideBar(true)}
              className="lg:hidden p-2 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
            >
              <MdOutlineMenu
                size={24}
                className="text-gray-700 dark:text-gray-300"
              />
            </button>
          </div>
        </div>
      </header>

      {/* ── Mobile Sidebar ── */}
      {openSideBar && (
        <div
          id="overlay"
          className="fixed inset-0 z-[60] bg-black/40 backdrop-blur-sm lg:hidden"
          onClick={handleOverlayClick}
        >
          <div
            className="absolute top-0 right-0 h-full w-72 bg-white dark:bg-gray-900 shadow-xl flex flex-col"
            onClick={(e) => e.stopPropagation()}
          >
            {/* Sidebar header */}
            <div className="flex items-center justify-between px-5 py-4 border-b border-gray-200 dark:border-gray-800">
              <Link
                href="/"
                className="flex items-center gap-2"
                onClick={() => setOpenSideBar(false)}
              >
                <div className="w-8 h-8 bg-gradient-to-br from-blue-600 to-purple-600 rounded-lg flex items-center justify-center">
                  <span className="text-white font-bold text-sm">E</span>
                </div>
                <span className="text-lg font-bold bg-gradient-to-r from-blue-600 to-purple-600 bg-clip-text text-transparent">
                  ELearning
                </span>
              </Link>
              <button
                onClick={() => setOpenSideBar(false)}
                className="p-1.5 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
              >
                <MdClose
                  size={20}
                  className="text-gray-600 dark:text-gray-300"
                />
              </button>
            </div>

            {/* Nav items */}
            <div className="flex-1 overflow-y-auto py-4 px-2">
              <NavItems activeItem={activeItem} isMobile={true} />
            </div>

            {/* Sidebar footer */}
            <div className="px-5 py-4 border-t border-gray-200 dark:border-gray-800 space-y-3">
              {user ? (
                <Link
                  href="/profile"
                  onClick={() => setOpenSideBar(false)}
                  className="flex items-center gap-3 px-3 py-2 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
                >
                  <Image
                    src={user?.avatar?.url || avatar}
                    alt="avatar"
                    width={32}
                    height={32}
                    className="rounded-full object-cover"
                  />
                  <span className="text-sm font-medium text-gray-800 dark:text-gray-200">
                    {user?.name}
                  </span>
                </Link>
              ) : (
                <button
                  onClick={() => {
                    setOpen(true);
                    setOpenSideBar(false);
                  }}
                  className="w-full flex items-center justify-center gap-2 py-2.5 bg-gradient-to-r from-blue-600 to-purple-600 text-white text-sm font-medium rounded-lg hover:opacity-90 transition-opacity"
                >
                  <MdPerson size={18} />
                  Sign In
                </button>
              )}
              <p className="text-center text-xs text-gray-400 dark:text-gray-600">
                © 2026 ELearning. All rights reserved.
              </p>
            </div>
          </div>
        </div>
      )}

      {/* ── Modals ── */}
      {open && route === "Login" && (
        <CustomModel
          open={open}
          setOpen={setOpen}
          activeItem={activeItem}
          Component={Login}
          setRoute={setRoute}
        />
      )}
      {open && route === "Sign-Up" && (
        <CustomModel
          open={open}
          setOpen={setOpen}
          activeItem={activeItem}
          Component={SignUp}
          setRoute={setRoute}
        />
      )}
      {open && route === "Verification" && (
        <CustomModel
          open={open}
          setOpen={setOpen}
          activeItem={activeItem}
          Component={Verification}
          setRoute={setRoute}
        />
      )}
    </div>
  );
};

export default Header;
