/* eslint-disable @typescript-eslint/no-explicit-any */
"use client";
import { FC, useEffect, useState } from "react";
import * as Yup from "yup";
import { useFormik } from "formik";
import {
  AiFillGithub,
  AiOutlineEye,
  AiOutlineEyeInvisible,
} from "react-icons/ai";
import { FcGoogle } from "react-icons/fc";
import toast from "react-hot-toast";
import { useRegisterMutation } from "@/redux/features/auth/authApi";
type Props = {
  setRoute: (route: string) => void;
};
const schema = Yup.object().shape({
  name: Yup.string().required("Please enter your name"),
  email: Yup.string()
    .email("invalid email")
    .required("Please enter your email"),
  password: Yup.string()
    .required("Please enter your password")
    .min(6, "Password must be at least 6 characters"),
});
const SignUp: FC<Props> = ({ setRoute }) => {
  const [show, setShow] = useState(false);
  const [register, { data, error, isSuccess }] = useRegisterMutation();
  const formik = useFormik({
    initialValues: {
      name: "",
      email: "",
      password: "",
    },
    validationSchema: schema,
    onSubmit: async ({
      name,
      email,
      password,
    }: {
      name: string;
      email: string;
      password: string;
    }) => {
      const data={name,email,password}
      await register(data);
    },
  });

  const { errors, touched, values, handleSubmit, handleChange } = formik;
useEffect(()=>{
    if(isSuccess){
        const message = data?.message || "Registration successful";
        toast.success(message);
        setRoute("Verification");
        if (error) {
          const errorData = error as any
          toast.error(errorData.data.message);
        }
    }
},[isSuccess,error])
  return (
    <div className="w-full">
      <h1 className="text-[25px] text-black dark:text-white font-medium font-poppins text-center py-2">
        Join to Elearning
      </h1>
      <form onSubmit={handleSubmit}>
        <div className="mb-3">
          <label
            className="text-[16px] font-poppins text-black dark:text-white"
            htmlFor="email"
          >
            Enter your name
          </label>
          <input
            type="text"
            name=""
            value={values.name}
            onChange={handleChange}
            id="name"
            placeholder="example"
            className={`${errors.name && touched.name && "border-red-500"} w-full text-black dark:text-white bg-transparent border rounded h-[40px] px-2 outline-none mt-[10px] font-poppins`}
          />
          {errors.name && touched.name && (
            <span className="text-red-500 pt-2 block">{errors.name}</span>
          )}
        </div>
        <label
          className="text-[16px] font-poppins text-black dark:text-white"
          htmlFor="email"
        >
          Enter your email
        </label>
        <input
          type="email"
          name=""
          value={values.email}
          onChange={handleChange}
          id="email"
          placeholder="example@gmail.com"
          className={`${errors.email && touched.email && "border-red-500"} w-full text-black dark:text-white bg-transparent border rounded h-[40px] px-2 outline-none mt-[10px] font-poppins`}
        />
        {errors.email && touched.email && (
          <span className="text-red-500 pt-2 block">{errors.email}</span>
        )}
        <div className="w-full mt-5 relative mb-1">
          <label
            className="text-[16px] font-poppins text-black dark:text-white"
            htmlFor="password"
          >
            Enter your password
          </label>
          <input
            type={show ? "text" : "password"}
            name=""
            value={values.password}
            onChange={handleChange}
            id="password"
            placeholder="password"
            className={`${errors.password && touched.password && "border-red-500"} w-full text-black dark:text-white bg-transparent border rounded h-[40px] px-2 outline-none mt-[10px] font-poppins`}
          />
          {!show ? (
            <AiOutlineEyeInvisible
              className="absolute bottom-3 right-2 z-1 cursor-pointer text-black dark:text-white"
              size={20}
              onClick={() => setShow(true)}
            />
          ) : (
            <AiOutlineEye
              className="absolute bottom-3 right-2 z-1 cursor-pointer text-black dark:text-white"
              size={20}
              onClick={() => setShow(false)}
            />
          )}
          {errors.password && touched.password && (
            <span className="text-red-500 pt-2 block">{errors.password}</span>
          )}
        </div>
        <div className="w-full mt-5">
          <input
            type="submit"
            value="Sign Up"
            className="flex flex-row justify-center items-center py-3 px-6 rounded-full cursor-pointer bg-[#2190ff] min-h-[45px] w-full text-[16px] font-poppins font-semibold"
          />
        </div>
        <br />
        <h5 className="text-center pt-4 font-poppins text-[14px] text-black dark:text-white">
          Or join with
        </h5>
        <div className="flex items-center justify-center my-3">
          <FcGoogle size={30} className="cursor-pointer mr-2" />
          <AiFillGithub
            size={30}
            className="cursor-pointer ml-2 text-black dark:text-white"
          />
        </div>
        <h5 className="text-center pt-4 font-poppins text-[14px]">
          Already have an account?{" "}
          <span
            className="text-[#2190ff] pl-1 cursor-pointer"
            onClick={() => setRoute("Login")}
          >
            Sign in
          </span>
        </h5>
      </form>
      <br />
    </div>
  );
};

export default SignUp;
