"use client";
import Link from "next/link";
import React, { FC } from "react";
import { usePathname } from "next/navigation";

export const navItemsData = [
  {
    name: "Home",
    url: "/",
  },
  {
    name: "Courses",
    url: "/courses",
  },
  {
    name: "About",
    url: "/about",
  },
  {
    name: "Policy",
    url: "/policy",
  },
  {
    name: "FAQ",
    url: "/faq",
  },
];

type Props = {
  activeItem: number;
  isMobile: boolean;
};

const NavItems: FC<Props> = ({ activeItem, isMobile }) => {
  const pathname = usePathname();

  return (
    <>
      {/* Desktop Navigation */}
      {!isMobile && (
        <nav className="hidden lg:flex items-center gap-1">
          {navItemsData.map((item, index) => {
            const isActive = activeItem === index || pathname === item.url;

            return (
              <Link
                href={item.url}
                key={index}
                className={`
                  relative px-4 py-2 rounded-lg font-medium text-[15px] transition-all duration-300
                  ${
                    isActive
                      ? "text-blue-600 dark:text-blue-400"
                      : "text-gray-700 dark:text-gray-300 hover:text-blue-600 dark:hover:text-blue-400"
                  }
                `}
              >
                {item.name}
                {isActive && (
                  <span className="absolute bottom-0 left-1/2 -translate-x-1/2 w-1/2 h-0.5 bg-gradient-to-r from-blue-600 to-purple-600 rounded-full" />
                )}
              </Link>
            );
          })}
        </nav>
      )}

      {/* Mobile Navigation */}
      {isMobile && (
        <nav className="lg:hidden w-full">
          <div className="flex flex-col space-y-1 px-4">
            {navItemsData.map((item, index) => {
              const isActive = activeItem === index || pathname === item.url;

              return (
                <Link
                  href={item.url}
                  key={index}
                  className={`
                    relative flex items-center gap-3 px-4 py-3 rounded-lg font-medium text-[16px] transition-all duration-200
                    ${
                      isActive
                        ? "bg-gradient-to-r from-blue-50 to-purple-50 dark:from-blue-900/20 dark:to-purple-900/20 text-blue-600 dark:text-blue-400"
                        : "text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-800"
                    }
                  `}
                >
                  {isActive && (
                    <span className="absolute left-0 top-1/2 -translate-y-1/2 w-1 h-8 bg-gradient-to-b from-blue-600 to-purple-600 rounded-r-full" />
                  )}
                  <span>{item.name}</span>
                </Link>
              );
            })}
          </div>
        </nav>
      )}
    </>
  );
};

export default NavItems;
