/* eslint-disable @typescript-eslint/no-explicit-any */
"use client";
import { useActivationMutation } from '@/redux/features/auth/authApi';
import React, { FC, useEffect, useRef, useState } from 'react'
import toast from 'react-hot-toast';
import { VscWorkspaceTrusted } from 'react-icons/vsc';
import { useSelector } from 'react-redux';

type Props = {
    setRoute: (route: string) => void
}
type VarifyNumber = {
  "0": string;
  "1": string;
  "2": string;
  "3": string;
};

const Verification: FC<Props> = ({setRoute}) => {
  const {token}= useSelector((state:any)=>state.auth)  
  const [activation, { isSuccess, error }] = useActivationMutation();
  const [invalidError, setInvalidError] = useState(false);
    useEffect(() => {
      if(isSuccess){
        toast.success("Account Activated Successfully");
        setRoute("Login")
      }
      if(error){
        if("data" in error){
          const errorData = error.data as any;
          toast.error(errorData.message);
          // setInvalidError(true);
        }else{
          toast.error("Something went wrong");
        }
      }
    },[isSuccess, error])
  const inputRefs =[
        useRef<HTMLInputElement>(null),
        useRef<HTMLInputElement>(null),
        useRef<HTMLInputElement>(null),
        useRef<HTMLInputElement>(null),
    ]
    const [verifyNumber, setVerifyNumber]=useState<VarifyNumber>({
        0:"",
        1:"",
        2:"",
        3:""
    })
    const verificationHandler =async()=>{
        const verificationNumber = Object.values(verifyNumber).join("")
        if(verificationNumber.length !== 4){
            setInvalidError(true);
            return;
        }
        const data = {activation_token: token, activation_code: verificationNumber}
        await activation(data);
    }
    const handleInputChange =(index: number, value: string)=>{
        setInvalidError(false);
        const newVarifyNumber= {...verifyNumber,[index]:value}
        setVerifyNumber(newVarifyNumber);
        if(value === "" && index > 0){
            inputRefs[index - 1].current?.focus()
        } else if(value.length === 1 && index < 3){
            inputRefs[index + 1].current?.focus();
        }
    }
  return (
    <div>
      <h1 className="text-[25px] text-black dark:text-white font-medium font-poppins text-center py-2">
        Verify Your Account
      </h1>
      <div className="w-full flex items-center justify-center mt-2">
        <div className="w-[80px] h-[80px] rounded-full bg-[#4970f2] flex items-center justify-center">
          <VscWorkspaceTrusted size={40} />
        </div>
      </div>
      <br />
      <br />
      <div className="m-auto flex items-center justify-around">
        {Object.keys(verifyNumber).map((key, index) => (
          <input
            type="text"
            key={index}
            ref={inputRefs[index]}
            className={`${invalidError ? "border-red-500 shadow" : "dark:border-white border-[#0000004a]"} w-[65px] h-[65px] bg-transparent border-[3px] rounded-[10px] flex items-center text-black dark:text-white justify-center text-[18px] font-poppins outline-none text-center`}
            placeholder=""
            maxLength={1}
            value={verifyNumber[key as keyof VarifyNumber]}
            onChange={(e) => handleInputChange(index, e.target.value)}
          />
        ))}
      </div>
      <br />
      <br />
      <div className="w-full flex justify-center">
        <button
          className="flex flex-row justify-center items-center py-3 px-6 rounded-full cursor-pointer bg-[#2190ff] min-h-[45px] w-full text-[16px] font-poppins font-semibold"
          onClick={verificationHandler}
        >
          Verify QTP
        </button>
      </div>
      <br />
      <h5 className='text-center pt-4 font-poppins text-[14px] text-black dark:text-white'>
        Go back to sign in?
        <span className='text-[#2190ff] pl-1 cursor-pointer' onClick={()=>setRoute("Login")}>
            Sign in
        </span>
      </h5>
    </div>
  );
}

export default Verification